  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B033",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made individual superconducting circuits into controllable atoms coupled to microwave photons, creating a new experimental platform for quantum optics and quantum information.",
        "attribution": "Blais supplied the key theoretical framework; Wallraff and Schoelkopf helped establish and demonstrate the experimental architecture. This selection recognizes both the theory and its decisive realization.",
        "maturity": "The platform has been independently developed and used for more than two decades, with increasingly precise control and a broad body of reproducible results.",
        "uncertainties": [
          "The boundaries between the foundational proposal, early demonstrations, and later engineering advances make the precise division of credit difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information could be protected despite the fragility of quantum states, and topological codes connected this challenge to deep physics.",
        "attribution": "Shor and Steane introduced influential error-correcting codes, while Kitaev developed the topological-code approach and its physical implications. Their contributions are distinct and complementary.",
        "maturity": "The theory is established, and experimental demonstrations have progressed from small codes toward repeated error correction. Practical fault tolerance remains an open technical challenge.",
        "uncertainties": [
          "The route from foundational codes to scalable fault tolerance is not yet settled."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Paul B. Corkum",
        "Maciej Lewenstein"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision picture transformed strong-field laser physics and enabled attosecond science, making electron motion within atoms experimentally accessible on its natural timescale.",
        "attribution": "Corkum's physical model and Lewenstein's quantum treatment provided central, complementary foundations for understanding and using the process.",
        "maturity": "The framework has been tested across many systems and underlies a mature experimental field with sustained scientific output.",
        "uncertainties": [
          "The broader development of attosecond methods involved many experimental and theoretical contributors beyond the two selected here."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks enabled a major improvement in precision timekeeping and opened tests of fundamental physics using exceptionally stable atomic transitions.",
        "attribution": "Katori and Ye made leading, complementary contributions to the clock concept and its experimental realization.",
        "maturity": "The technology is now highly developed, with independent groups achieving remarkable accuracy and stability.",
        "uncertainties": [
          "The path from laboratory clock performance to a redefinition of the second is still in progress."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "Philip St. J. Russell"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps established a powerful way to control light through structure, helping create the fields of photonic crystals and photonic crystal fibers.",
        "attribution": "Yablonovitch and John independently articulated central photonic-crystal ideas; Russell's photonic crystal fibers brought band-gap design into an important and distinctive optical platform.",
        "maturity": "The underlying physics is well established and has produced durable experimental and technological directions.",
        "uncertainties": [
          "The candidate combines related but partly distinct lines of work, so a three-person award would need a carefully bounded citation."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory gave physicists a tractable framework for strongly correlated electrons and clarified how local quantum dynamics can drive collective electronic phases.",
        "attribution": "Georges and Kotliar were central to formulating and developing the method, while Vollhardt's work helped establish its foundations and reach.",
        "maturity": "The method has been extensively tested, generalized, and applied across correlated-material problems.",
        "uncertainties": [
          "Its strongest results depend on approximations and extensions, and the intellectual credit spans a larger community than these three."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B050",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed that moiré structures can create tunable regimes of strong electronic correlation, opening a broad new direction in quantum materials.",
        "attribution": "Bistritzer and MacDonald predicted the special-angle flat-band mechanism; Jarillo-Herrero's experiments demonstrated the resulting correlated phases.",
        "maturity": "The platform has inspired extensive experimental and theoretical work, but the interpretation of some phases and their relation to superconductivity remain active questions.",
        "uncertainties": [
          "The degree to which the observed phenomena form a coherent, general account of the central discovery is still being resolved."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light provides a way to reduce quantum measurement noise below the standard quantum limit and has made quantum optics directly relevant to precision interferometry.",
        "attribution": "Caves established the key measurement-noise framework; Kimble advanced the experimental foundations, and Mavalvala helped bring squeezed-light techniques into gravitational-wave interferometry.",
        "maturity": "Squeezed-light methods are demonstrated in operating gravitational-wave detectors, with ongoing improvements and further applications.",
        "uncertainties": [
          "The advance was cumulative, involving many experimental teams and contributors, including work represented by the other credited candidate."
        ]
      }
    }
  ]
}
